import math

def max_fill(grid, capacity):
    total_water = 0
    for row in grid:
        total_water += sum(row)
    return math.ceil(total_water / capacity)

def make_palindrome(string: str) -> str:
    n = len(string)
    if n == 0:
        return ''

    for i in range(n, -1, -1):
        if is_palindrome(string[:i]):
            prefix_to_reverse = string[i:]
            break

    return string + prefix_to_reverse[::-1]

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    txt = txt.rstrip()
    words = txt.split()
    last_word = words[-1]
    return len(last_word) == 1 and last_word.isalpha()

def is_nested(string):
    count = 0
    for char in string:
        if char == '[':
            count += 1
        elif char == ']':
            count -= 1
        if count < 0:
            return False
    return count > 0

def starts_one_ends(n):
    if n == 1:
        return 1
    return 2 * 10**(n-1) - 10**(n-2)

