def check_dict_case(dct):
    if not dct:
        return False

    has_lower = has_upper = False

    for key in dct.keys():
        if not isinstance(key, str):
            return False
        if key.islower():
            has_lower = True
        elif key.isupper():
            has_upper = True
        if has_lower and has_upper:
            return False

    return True

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    prime_factors_count = 0
    for i in range(2, int(a**0.5) + 1):
        if is_prime(i) and a % i == 0:
            prime_factors_count += 1
    return prime_factors_count == 3
